import { useState, useEffect } from 'react';
import { Download, Share2, PlusSquare, X, Smartphone, CheckCircle2, HelpCircle } from 'lucide-react';
import { getPlatform, isStandalone } from '../lib/utils';
import { getInstallPrompt } from '../lib/pwa';

interface PwaInstallBannerProps {
  forceOpen?: boolean;
  onClose?: () => void;
}

export function PwaInstallBanner({ forceOpen = false, onClose }: PwaInstallBannerProps) {
  const [deferredPrompt, setDeferredPrompt] = useState<any>(() => getInstallPrompt());
  const [installed, setInstalled] = useState<boolean>(() => isStandalone());
  const [installing, setInstalling] = useState<boolean>(false);
  const [showGuideModal, setShowGuideModal] = useState<boolean>(false);
  const [dismissed, setDismissed] = useState<boolean>(() => {
    try {
      return sessionStorage.getItem('cronos_pwa_dismissed') === 'true';
    } catch {
      return false;
    }
  });
  const [platform] = useState<'ios' | 'android' | 'web'>(() => getPlatform());

  useEffect(() => {
    function handlePrompt(e: Event) {
      e.preventDefault();
      setDeferredPrompt(e);
      window.__pwaInstallPrompt = e;
    }

    function handleCustomPrompt(e: any) {
      if (e.detail) {
        setDeferredPrompt(e.detail);
      }
    }

    function handleInstalled() {
      setInstalled(true);
      setDeferredPrompt(null);
      window.__pwaInstallPrompt = null;
    }

    window.addEventListener('beforeinstallprompt', handlePrompt);
    window.addEventListener('pwa-prompt-available', handleCustomPrompt);
    window.addEventListener('appinstalled', handleInstalled);
    window.addEventListener('pwa-installed', handleInstalled);

    return () => {
      window.removeEventListener('beforeinstallprompt', handlePrompt);
      window.removeEventListener('pwa-prompt-available', handleCustomPrompt);
      window.removeEventListener('appinstalled', handleInstalled);
      window.removeEventListener('pwa-installed', handleInstalled);
    };
  }, []);

  async function handleInstallClick() {
    const promptObj = deferredPrompt || getInstallPrompt();

    if (promptObj) {
      try {
        setInstalling(true);
        await promptObj.prompt();
        const choice = await promptObj.userChoice;
        if (choice?.outcome === 'accepted') {
          setInstalled(true);
          sessionStorage.setItem('cronos_pwa_installed', 'true');
        }
        setDeferredPrompt(null);
        window.__pwaInstallPrompt = null;
      } catch (err) {
        console.error('[PWA] Error launching install prompt:', err);
      } finally {
        setInstalling(false);
      }
    } else {
      // If browser has not fired beforeinstallprompt or platform is iOS
      setShowGuideModal(true);
    }
  }

  function handleDismiss() {
    setDismissed(true);
    sessionStorage.setItem('cronos_pwa_dismissed', 'true');
    if (onClose) onClose();
  }

  // Already running in standalone PWA mode
  if (installed && !forceOpen) return null;
  // User dismissed and not forced from menu
  if (dismissed && !forceOpen) return null;

  return (
    <>
      <div
        className="card"
        style={{
          background: 'linear-gradient(135deg, rgba(255, 242, 26, 0.10) 0%, rgba(23, 26, 33, 0.98) 100%)',
          border: '1px solid rgba(255, 242, 26, 0.3)',
          borderRadius: 'var(--radius-xl)',
          padding: '16px',
          position: 'relative',
          boxShadow: '0 8px 30px rgba(0, 0, 0, 0.45)',
          marginBottom: forceOpen ? 0 : 'var(--space-4)',
        }}
      >
        {!forceOpen && (
          <button
            onClick={handleDismiss}
            aria-label="Fechar aviso"
            className="btn-ghost btn-icon"
            style={{ position: 'absolute', top: 8, right: 8, width: 28, height: 28, minHeight: 28, color: 'var(--text-muted)' }}
          >
            <X size={16} />
          </button>
        )}

        <div style={{ display: 'flex', alignItems: 'flex-start', gap: 14 }}>
          {/* App Icon preview */}
          <div
            style={{
              width: 48,
              height: 48,
              borderRadius: 'var(--radius-lg)',
              background: 'linear-gradient(135deg, #FFF21A 0%, #D97706 100%)',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              flexShrink: 0,
              boxShadow: '0 4px 12px rgba(255, 242, 26, 0.25)',
              padding: 6,
            }}
          >
            <img
              src="./icons/icon-192.png"
              alt="Cronos"
              style={{ width: '100%', height: '100%', objectFit: 'contain', borderRadius: 'var(--radius-md)' }}
              onError={(e) => {
                // Fallback icon if image loading fails
                (e.target as HTMLElement).style.display = 'none';
              }}
            />
          </div>

          <div style={{ flex: 1, paddingRight: forceOpen ? 0 : 20 }}>
            <div style={{ display: 'flex', alignItems: 'center', gap: 6, marginBottom: 4 }}>
              <h4 style={{ fontSize: 'var(--text-sm)', fontWeight: 700, color: '#fff', margin: 0 }}>
                Instalar Cronos no seu aparelho
              </h4>
            </div>

            <p style={{ fontSize: 'var(--text-xs)', color: 'var(--text-muted)', lineHeight: 1.45, marginBottom: 12 }}>
              Tenha a experiência de app nativo em tela cheia com notificações push de vencimento.
            </p>

            {installed ? (
              <div style={{ display: 'flex', alignItems: 'center', gap: 6, color: 'var(--ok)', fontSize: 13, fontWeight: 600 }}>
                <CheckCircle2 size={16} />
                <span>Aplicativo já instalado no dispositivo!</span>
              </div>
            ) : platform === 'ios' ? (
              <div
                style={{
                  background: 'var(--surface-2)',
                  borderRadius: 'var(--radius-md)',
                  padding: '10px 12px',
                  fontSize: 12,
                  color: 'var(--text)',
                  display: 'flex',
                  flexDirection: 'column',
                  gap: 8,
                  border: '1px solid var(--border)',
                }}
              >
                <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
                  <Share2 size={15} color="var(--brand)" />
                  <span>1. No Safari, toque no botão <strong>Compartilhar</strong></span>
                </div>
                <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
                  <PlusSquare size={15} color="var(--brand)" />
                  <span>2. Escolha <strong>Adicionar à Tela de Início</strong></span>
                </div>
              </div>
            ) : (
              <div style={{ display: 'flex', flexWrap: 'wrap', alignItems: 'center', gap: 8 }}>
                <button
                  id="btn-install-pwa"
                  className="btn-primary"
                  onClick={handleInstallClick}
                  disabled={installing}
                  style={{ fontSize: 13, height: 38, padding: '0 18px', fontWeight: 700 }}
                >
                  <Download size={15} style={{ marginRight: 6 }} />
                  {installing ? 'Abrindo instalação...' : deferredPrompt ? 'Instalar Agora' : 'Instalar Aplicativo'}
                </button>

                {!deferredPrompt && (
                  <button
                    className="btn-ghost"
                    onClick={() => setShowGuideModal(true)}
                    style={{ fontSize: 12, height: 38, padding: '0 10px', color: 'var(--brand)' }}
                  >
                    <HelpCircle size={14} style={{ marginRight: 4 }} />
                    Como instalar?
                  </button>
                )}
              </div>
            )}
          </div>
        </div>
      </div>

      {/* Manual installation guide modal (shown if native prompt is not available) */}
      {showGuideModal && (
        <div
          style={{
            position: 'fixed',
            inset: 0,
            background: 'rgba(0,0,0,0.75)',
            backdropFilter: 'blur(8px)',
            zIndex: 9999,
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            padding: 16,
          }}
          onClick={() => setShowGuideModal(false)}
        >
          <div
            className="card"
            style={{
              maxWidth: 420,
              width: '100%',
              background: 'var(--surface)',
              border: '1px solid var(--border)',
              borderRadius: 'var(--radius-xl)',
              padding: 20,
              boxShadow: '0 16px 40px rgba(0,0,0,0.6)',
            }}
            onClick={(e) => e.stopPropagation()}
          >
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 14 }}>
              <div style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
                <div style={{
                  width: 36, height: 36, borderRadius: 'var(--radius-md)',
                  background: 'var(--brand)', display: 'flex', alignItems: 'center', justifyContent: 'center'
                }}>
                  <Smartphone size={20} color="var(--on-brand)" />
                </div>
                <h3 style={{ fontSize: 'var(--text-base)', fontWeight: 700, margin: 0 }}>
                  Instalar no Navegador
                </h3>
              </div>
              <button
                onClick={() => setShowGuideModal(false)}
                className="btn-ghost btn-icon"
                style={{ width: 32, height: 32 }}
              >
                <X size={18} />
              </button>
            </div>

            <p style={{ fontSize: 'var(--text-xs)', color: 'var(--text-muted)', lineHeight: 1.5, marginBottom: 16 }}>
              Para instalar o Cronos diretamente no Android / Google Chrome:
            </p>

            <div style={{ display: 'flex', flexDirection: 'column', gap: 10, marginBottom: 20 }}>
              <div style={{
                display: 'flex', alignItems: 'flex-start', gap: 12,
                background: 'var(--surface-2)', padding: '10px 14px', borderRadius: 'var(--radius-lg)',
                border: '1px solid var(--border)',
              }}>
                <span style={{
                  width: 24, height: 24, borderRadius: '50%', background: 'var(--brand)',
                  color: 'var(--on-brand)', display: 'flex', alignItems: 'center', justifyContent: 'center',
                  fontSize: 12, fontWeight: 700, flexShrink: 0,
                }}>1</span>
                <span style={{ fontSize: 13, color: 'var(--text)' }}>
                  Toque nos <strong>três pontos (⋮)</strong> no canto superior direito do Chrome.
                </span>
              </div>

              <div style={{
                display: 'flex', alignItems: 'flex-start', gap: 12,
                background: 'var(--surface-2)', padding: '10px 14px', borderRadius: 'var(--radius-lg)',
                border: '1px solid var(--border)',
              }}>
                <span style={{
                  width: 24, height: 24, borderRadius: '50%', background: 'var(--brand)',
                  color: 'var(--on-brand)', display: 'flex', alignItems: 'center', justifyContent: 'center',
                  fontSize: 12, fontWeight: 700, flexShrink: 0,
                }}>2</span>
                <span style={{ fontSize: 13, color: 'var(--text)' }}>
                  Toque na opção <strong>"Instalar aplicativo"</strong> ou <strong>"Adicionar à tela inicial"</strong>.
                </span>
              </div>

              <div style={{
                display: 'flex', alignItems: 'flex-start', gap: 12,
                background: 'var(--surface-2)', padding: '10px 14px', borderRadius: 'var(--radius-lg)',
                border: '1px solid var(--border)',
              }}>
                <span style={{
                  width: 24, height: 24, borderRadius: '50%', background: 'var(--brand)',
                  color: 'var(--on-brand)', display: 'flex', alignItems: 'center', justifyContent: 'center',
                  fontSize: 12, fontWeight: 700, flexShrink: 0,
                }}>3</span>
                <span style={{ fontSize: 13, color: 'var(--text)' }}>
                  Confirme tocando em <strong>"Instalar"</strong> no diálogo nativo.
                </span>
              </div>
            </div>

            <button
              className="btn-primary"
              style={{ width: '100%' }}
              onClick={() => {
                setShowGuideModal(false);
                // Also trigger prompt if available now
                const p = getInstallPrompt();
                if (p) {
                  p.prompt();
                }
              }}
            >
              Entendido
            </button>
          </div>
        </div>
      )}
    </>
  );
}
