import { Routes, Route, Navigate, Outlet } from 'react-router-dom';
import { useAuth } from './contexts/AuthContext';
import { BottomNav } from './components/BottomNav';
import { Sidebar } from './components/Sidebar';
import LoginPage from './pages/LoginPage';
import HomePage from './pages/HomePage';
import BillsPage from './pages/BillsPage';
import BillDetailPage from './pages/BillDetailPage';
import EditBillPage from './pages/EditBillPage';
import AddBillPage from './pages/AddBillPage';
import ManualBillPage from './pages/add/ManualBillPage';
import ScanBillPage from './pages/add/ScanBillPage';
import UploadBillPage from './pages/add/UploadBillPage';
import AssistantPage from './pages/AssistantPage';
import MorePage from './pages/MorePage';
import SuppliersPage from './pages/SuppliersPage';
import CategoriesPage from './pages/CategoriesPage';
import RecurrencesPage from './pages/RecurrencesPage';
import ReportsPage from './pages/ReportsPage';
import NotificationsPage from './pages/NotificationsPage';
import TeamPage from './pages/TeamPage';
import SettingsPage from './pages/SettingsPage';

// Protected layout: shows Sidebar on desktop, BottomNav on mobile, guards auth
function AppLayout() {
  const { session, loading } = useAuth();

  if (loading) {
    return (
      <div style={{
        minHeight: '100dvh', display: 'flex', alignItems: 'center',
        justifyContent: 'center', flexDirection: 'column', gap: 16,
        background: 'var(--bg)',
      }}>
        <div style={{
          width: 60, height: 60, borderRadius: '50%',
          background: 'var(--brand)', display: 'flex',
          alignItems: 'center', justifyContent: 'center',
          boxShadow: 'var(--shadow-brand)',
        }}>
          <svg width="30" height="30" viewBox="0 0 24 24" fill="none" stroke="var(--on-brand)" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
            <circle cx="12" cy="12" r="10"/>
            <polyline points="12 6 12 12 16 14"/>
          </svg>
        </div>
        <p style={{ color: 'var(--text-muted)', fontSize: 14 }}>Carregando...</p>
      </div>
    );
  }

  if (!session) {
    return <Navigate to="/login" replace />;
  }

  return (
    <div className="app-shell">
      <Sidebar />
      <div className="main-content">
        <Outlet />
      </div>
      <BottomNav />
    </div>
  );
}

// Redirect authenticated users away from login
function PublicRoute() {
  const { session, loading } = useAuth();
  if (loading) return null;
  if (session) return <Navigate to="/" replace />;
  return <Outlet />;
}

export function AppRouter() {
  return (
    <Routes>
      {/* Public routes */}
      <Route element={<PublicRoute />}>
        <Route path="/login" element={<LoginPage />} />
      </Route>

      {/* Protected routes with bottom nav */}
      <Route element={<AppLayout />}>
        {/* Core */}
        <Route path="/" element={<HomePage />} />
        <Route path="/boletos" element={<BillsPage />} />
        <Route path="/boletos/:id" element={<BillDetailPage />} />
        <Route path="/boletos/:id/editar" element={<EditBillPage />} />

        {/* Add flows */}
        <Route path="/adicionar" element={<AddBillPage />} />
        <Route path="/adicionar/manual" element={<ManualBillPage />} />
        <Route path="/adicionar/escanear" element={<ScanBillPage />} />
        <Route path="/adicionar/upload" element={<UploadBillPage />} />

        {/* Assistente */}
        <Route path="/assistente" element={<AssistantPage />} />

        {/* More menu pages */}
        <Route path="/mais" element={<MorePage />} />
        <Route path="/fornecedores" element={<SuppliersPage />} />
        <Route path="/categorias" element={<CategoriesPage />} />
        <Route path="/recorrencias" element={<RecurrencesPage />} />
        <Route path="/relatorios" element={<ReportsPage />} />
        <Route path="/notificacoes" element={<NotificationsPage />} />
        <Route path="/equipe" element={<TeamPage />} />
        <Route path="/configuracoes" element={<SettingsPage />} />
      </Route>

      {/* Catch-all */}
      <Route path="*" element={<Navigate to="/" replace />} />
    </Routes>
  );
}
