import { useState } from 'react';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { z } from 'zod';
import { useAuth } from '../contexts/AuthContext';
import { Lock, Mail, Clock, AlertCircle } from 'lucide-react';
import { supabase } from '../lib/supabase';
import { useToast } from '../components/Toast';

const loginSchema = z.object({
  email: z.string().email('E-mail inválido'),
  password: z.string().min(6, 'Senha deve ter pelo menos 6 caracteres'),
});

type LoginForm = z.infer<typeof loginSchema>;

export default function LoginPage() {
  const { signIn } = useAuth();
  const { toast } = useToast();
  const [loading, setLoading] = useState(false);
  const [showReset, setShowReset] = useState(false);
  const [resetEmail, setResetEmail] = useState('');
  const [resetSent, setResetSent] = useState(false);

  const {
    register,
    handleSubmit,
    formState: { errors },
    setError,
  } = useForm<LoginForm>({ resolver: zodResolver(loginSchema) });

  async function onSubmit(data: LoginForm) {
    setLoading(true);
    const { error } = await signIn(data.email, data.password);
    setLoading(false);

    if (error) {
      if (error.message.includes('Invalid login')) {
        setError('password', { message: 'E-mail ou senha incorretos' });
      } else if (error.message.includes('not confirmed')) {
        toast('Confirme seu e-mail antes de entrar.', 'error');
      } else {
        toast('Erro ao entrar. Tente novamente.', 'error');
      }
    }
  }

  async function handleReset() {
    if (!resetEmail) return;
    const { error } = await supabase.auth.resetPasswordForEmail(resetEmail, {
      redirectTo: `${window.location.origin}/nova-senha`,
    });
    if (error) {
      toast('Erro ao enviar e-mail de recuperação.', 'error');
    } else {
      setResetSent(true);
    }
  }

  if (showReset) {
    return (
      <div style={{
        minHeight: '100dvh',
        display: 'flex',
        flexDirection: 'column',
        alignItems: 'center',
        justifyContent: 'center',
        padding: 'var(--space-6)',
        background: 'var(--bg)',
      }}>
        <div style={{ width: '100%', maxWidth: 360, textAlign: 'center' }}>
          <div style={{
            width: 64, height: 64, borderRadius: 'var(--radius-full)',
            background: 'var(--brand-dim)', display: 'flex',
            alignItems: 'center', justifyContent: 'center', margin: '0 auto var(--space-6)',
          }}>
            <Mail size={28} color="var(--brand)" />
          </div>

          {resetSent ? (
            <>
              <h1 style={{ fontSize: 'var(--text-xl)', marginBottom: 'var(--space-3)' }}>E-mail enviado</h1>
              <p style={{ color: 'var(--text-muted)', marginBottom: 'var(--space-6)' }}>
                Verifique sua caixa de entrada e siga as instruções para redefinir a senha.
              </p>
              <button className="btn btn-primary btn-full" onClick={() => setShowReset(false)}>
                Voltar ao login
              </button>
            </>
          ) : (
            <>
              <h1 style={{ fontSize: 'var(--text-xl)', marginBottom: 'var(--space-2)' }}>Recuperar senha</h1>
              <p style={{ color: 'var(--text-muted)', marginBottom: 'var(--space-6)' }}>
                Digite seu e-mail e enviaremos um link de recuperação.
              </p>
              <div className="input-group" style={{ marginBottom: 'var(--space-4)' }}>
                <input
                  id="reset-email"
                  className="input"
                  type="email"
                  placeholder="seu@email.com"
                  value={resetEmail}
                  onChange={e => setResetEmail(e.target.value)}
                  aria-label="E-mail para recuperação"
                />
              </div>
              <button className="btn btn-primary btn-full" onClick={handleReset} disabled={!resetEmail}>
                Enviar link de recuperação
              </button>
              <button
                className="btn btn-ghost btn-full"
                style={{ marginTop: 'var(--space-3)' }}
                onClick={() => setShowReset(false)}
              >
                Voltar
              </button>
            </>
          )}
        </div>
      </div>
    );
  }

  return (
    <div style={{
      minHeight: '100dvh',
      display: 'flex',
      flexDirection: 'column',
      alignItems: 'center',
      justifyContent: 'center',
      padding: 'var(--space-6)',
      background: 'var(--bg)',
      position: 'relative',
      overflow: 'hidden',
    }}>
      {/* Background decorative circles */}
      <div aria-hidden="true" style={{
        position: 'absolute', top: -120, right: -120,
        width: 400, height: 400, borderRadius: '50%',
        background: 'radial-gradient(circle, rgba(255,242,26,0.06) 0%, transparent 70%)',
        pointerEvents: 'none',
      }} />
      <div aria-hidden="true" style={{
        position: 'absolute', bottom: -80, left: -100,
        width: 300, height: 300, borderRadius: '50%',
        background: 'radial-gradient(circle, rgba(255,242,26,0.04) 0%, transparent 70%)',
        pointerEvents: 'none',
      }} />

      <div className="animate-fade-in" style={{ width: '100%', maxWidth: 360 }}>
        {/* Logo */}
        <div style={{ textAlign: 'center', marginBottom: 'var(--space-10)' }}>
          <div style={{
            width: 80, height: 80, borderRadius: 'var(--radius-full)',
            background: 'var(--brand)', display: 'flex',
            alignItems: 'center', justifyContent: 'center',
            margin: '0 auto var(--space-4)',
            boxShadow: 'var(--shadow-brand-lg)',
            animation: 'pulse-brand 3s ease-in-out infinite',
          }}>
            <Clock size={40} color="var(--on-brand)" strokeWidth={2} />
          </div>
          <h1 style={{
            fontFamily: 'Montserrat, sans-serif',
            fontSize: 'var(--text-2xl)',
            fontWeight: 900,
            letterSpacing: '-0.02em',
            color: 'var(--text)',
            textTransform: 'uppercase',
          }}>
            CRONOS
          </h1>
          <p style={{ color: 'var(--text-muted)', fontSize: 'var(--text-sm)', marginTop: 4 }}>
            Morpheus Relojoaria
          </p>
        </div>

        {/* Login form */}
        <form onSubmit={handleSubmit(onSubmit)} noValidate>
          <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--space-4)' }}>
            {/* Email */}
            <div className="input-group">
              <label htmlFor="email" className="input-label">E-mail</label>
              <div style={{ position: 'relative' }}>
                <Mail
                  size={18}
                  style={{
                    position: 'absolute', left: 14, top: '50%',
                    transform: 'translateY(-50%)', color: 'var(--text-subtle)',
                    pointerEvents: 'none',
                  }}
                  aria-hidden="true"
                />
                <input
                  id="email"
                  type="email"
                  className={`input ${errors.email ? 'input-error' : ''}`}
                  style={{ paddingLeft: 42 }}
                  placeholder="seu@email.com"
                  autoComplete="email"
                  aria-describedby={errors.email ? 'email-error' : undefined}
                  {...register('email')}
                />
              </div>
              {errors.email && (
                <span id="email-error" className="input-error-msg" role="alert">
                  <AlertCircle size={12} style={{ display: 'inline', marginRight: 4 }} />
                  {errors.email.message}
                </span>
              )}
            </div>

            {/* Password */}
            <div className="input-group">
              <label htmlFor="password" className="input-label">Senha</label>
              <div style={{ position: 'relative' }}>
                <Lock
                  size={18}
                  style={{
                    position: 'absolute', left: 14, top: '50%',
                    transform: 'translateY(-50%)', color: 'var(--text-subtle)',
                    pointerEvents: 'none',
                  }}
                  aria-hidden="true"
                />
                <input
                  id="password"
                  type="password"
                  className={`input ${errors.password ? 'input-error' : ''}`}
                  style={{ paddingLeft: 42 }}
                  placeholder="••••••••"
                  autoComplete="current-password"
                  aria-describedby={errors.password ? 'password-error' : undefined}
                  {...register('password')}
                />
              </div>
              {errors.password && (
                <span id="password-error" className="input-error-msg" role="alert">
                  <AlertCircle size={12} style={{ display: 'inline', marginRight: 4 }} />
                  {errors.password.message}
                </span>
              )}
            </div>

            <button
              id="btn-login"
              type="submit"
              className="btn btn-primary btn-full btn-lg"
              disabled={loading}
              aria-busy={loading}
            >
              {loading ? 'Entrando...' : 'Entrar'}
            </button>

            <button
              type="button"
              className="btn btn-ghost"
              onClick={() => setShowReset(true)}
              style={{ fontSize: 'var(--text-sm)', color: 'var(--text-muted)' }}
            >
              Esqueci minha senha
            </button>
          </div>
        </form>

        {/* Access notice */}
        <div style={{
          marginTop: 'var(--space-8)',
          padding: 'var(--space-4)',
          background: 'var(--surface)',
          borderRadius: 'var(--radius-md)',
          border: '1px solid var(--border)',
          textAlign: 'center',
        }}>
          <p style={{ fontSize: 'var(--text-xs)', color: 'var(--text-muted)', lineHeight: 1.6 }}>
            <Lock size={12} style={{ display: 'inline', marginRight: 4 }} aria-hidden="true" />
            Acesso por convite apenas. Para solicitar acesso, entre em contato com o administrador.
          </p>
        </div>
      </div>
    </div>
  );
}
