import { useState } from 'react';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { supabase } from '../lib/supabase';
import { useAuth } from '../contexts/AuthContext';
import { useToast } from '../components/Toast';
import {
  Truck, Plus, Search, Pencil, Trash2,
  ArrowLeft, AlertCircle, Building2, FileText,
} from 'lucide-react';
import { useNavigate } from 'react-router-dom';
import type { Supplier } from '../types/database';

function useSuppliers(orgId: string | undefined) {
  return useQuery({
    queryKey: ['suppliers', orgId],
    queryFn: async () => {
      if (!orgId) return [];
      const { data, error } = await supabase
        .from('suppliers')
        .select('*')
        .eq('org_id', orgId)
        .order('name');
      if (error) throw error;
      return (data ?? []) as Supplier[];
    },
    enabled: !!orgId,
  });
}

interface SupplierFormData {
  name: string;
  document: string;
  notes: string;
}

const emptyForm: SupplierFormData = { name: '', document: '', notes: '' };

export default function SuppliersPage() {
  const { currentOrg } = useAuth();
  const navigate = useNavigate();
  const { toast } = useToast();
  const queryClient = useQueryClient();
  const [search, setSearch] = useState('');
  const [showModal, setShowModal] = useState(false);
  const [editing, setEditing] = useState<Supplier | null>(null);
  const [form, setForm] = useState<SupplierFormData>(emptyForm);
  const [saving, setSaving] = useState(false);
  const [deleteTarget, setDeleteTarget] = useState<Supplier | null>(null);

  const { data: suppliers = [], isLoading } = useSuppliers(currentOrg?.org_id);

  const filtered = suppliers.filter(s =>
    s.name.toLowerCase().includes(search.toLowerCase()) ||
    s.document?.toLowerCase().includes(search.toLowerCase())
  );

  function openCreate() {
    setEditing(null);
    setForm(emptyForm);
    setShowModal(true);
  }

  function openEdit(supplier: Supplier) {
    setEditing(supplier);
    setForm({ name: supplier.name, document: supplier.document ?? '', notes: supplier.notes ?? '' });
    setShowModal(true);
  }

  async function handleSave() {
    if (!currentOrg || !form.name.trim()) {
      toast('Informe o nome do fornecedor.', 'error');
      return;
    }
    setSaving(true);
    try {
      if (editing) {
        const { error } = await supabase
          .from('suppliers')
          .update({ name: form.name.trim(), document: form.document || null, notes: form.notes || null })
          .eq('id', editing.id);
        if (error) throw error;
        toast('Fornecedor atualizado!', 'success');
      } else {
        const { error } = await supabase
          .from('suppliers')
          .insert({ org_id: currentOrg.org_id, name: form.name.trim(), document: form.document || null, notes: form.notes || null });
        if (error) throw error;
        toast('Fornecedor cadastrado!', 'success');
      }
      queryClient.invalidateQueries({ queryKey: ['suppliers'] });
      setShowModal(false);
    } catch {
      toast('Erro ao salvar fornecedor.', 'error');
    } finally {
      setSaving(false);
    }
  }

  const deleteMutation = useMutation({
    mutationFn: async (id: string) => {
      const { error } = await supabase.from('suppliers').delete().eq('id', id);
      if (error) throw error;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['suppliers'] });
      toast('Fornecedor excluído.', 'success');
      setDeleteTarget(null);
    },
    onError: () => toast('Erro ao excluir. Verifique se há boletos vinculados.', 'error'),
  });

  return (
    <main className="page" id="page-suppliers">
      <header className="page-header">
        <div className="container" style={{ display: 'flex', alignItems: 'center', gap: 'var(--space-3)' }}>
          <button className="btn-ghost btn-icon" onClick={() => navigate(-1)} aria-label="Voltar"
            style={{ width: 40, height: 40, minHeight: 40 }}>
            <ArrowLeft size={20} />
          </button>
          <h1 style={{ fontSize: 'var(--text-lg)', fontWeight: 700, flex: 1 }}>Fornecedores</h1>
          <button className="btn btn-primary" onClick={openCreate} id="btn-new-supplier" aria-label="Novo fornecedor">
            <Plus size={18} strokeWidth={2.5} />
            <span className="desktop-only">Novo</span>
          </button>
        </div>
      </header>

      <div className="page-content container">
        {/* Search */}
        <div className="search-wrapper">
          <Search size={18} className="search-icon" aria-hidden="true" />
          <input
            id="supplier-search"
            type="search"
            className="input search-input"
            placeholder="Buscar fornecedor..."
            value={search}
            onChange={e => setSearch(e.target.value)}
            aria-label="Buscar fornecedores"
          />
        </div>

        {/* List */}
        {isLoading ? (
          <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--space-3)' }}>
            {[...Array(4)].map((_, i) => (
              <div key={i} className="skeleton" style={{ height: 72, borderRadius: 'var(--radius-lg)' }} />
            ))}
          </div>
        ) : filtered.length === 0 ? (
          <div className="empty-state">
            <div className="empty-state-circles">
              <div className="empty-circle empty-circle-1" />
              <div className="empty-circle empty-circle-2" />
              <Truck size={48} color="var(--text-muted)" style={{ position: 'absolute', top: '50%', left: '50%', transform: 'translate(-50%, -50%)', zIndex: 1 }} aria-hidden="true" />
            </div>
            <h2>{search ? 'Nenhum resultado' : 'Sem fornecedores'}</h2>
            <p style={{ color: 'var(--text-muted)', fontSize: 'var(--text-sm)' }}>
              {search ? `Nenhum fornecedor para "${search}".` : 'Cadastre os seus fornecedores para vinculá-los aos boletos.'}
            </p>
            {!search && (
              <button className="btn btn-primary" onClick={openCreate}>
                <Plus size={16} /> Cadastrar fornecedor
              </button>
            )}
          </div>
        ) : (
          <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--space-2)' }}>
            {filtered.map(supplier => (
              <div
                key={supplier.id}
                className="card"
                style={{ display: 'flex', alignItems: 'center', gap: 'var(--space-3)', padding: 'var(--space-4)' }}
              >
                <div style={{
                  width: 44, height: 44, borderRadius: 'var(--radius-md)',
                  background: 'var(--surface-2)', display: 'flex',
                  alignItems: 'center', justifyContent: 'center', flexShrink: 0,
                }}>
                  <Building2 size={20} color="var(--text-muted)" />
                </div>
                <div style={{ flex: 1, minWidth: 0 }}>
                  <p style={{ fontWeight: 600, fontSize: 'var(--text-sm)', marginBottom: 2 }}>{supplier.name}</p>
                  {supplier.document && (
                    <p style={{ fontSize: 'var(--text-xs)', color: 'var(--text-muted)' }}>{supplier.document}</p>
                  )}
                  {supplier.notes && (
                    <p style={{ fontSize: 'var(--text-xs)', color: 'var(--text-subtle)', overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{supplier.notes}</p>
                  )}
                </div>
                <div style={{ display: 'flex', gap: 'var(--space-1)', flexShrink: 0 }}>
                  <button className="btn-ghost btn-icon btn-sm" onClick={() => openEdit(supplier)} aria-label={`Editar ${supplier.name}`}>
                    <Pencil size={16} />
                  </button>
                  <button
                    className="btn-ghost btn-icon btn-sm"
                    onClick={() => setDeleteTarget(supplier)}
                    aria-label={`Excluir ${supplier.name}`}
                    style={{ color: 'var(--urgent)' }}
                  >
                    <Trash2 size={16} />
                  </button>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>

      {/* Create/Edit Modal */}
      {showModal && (
        <div
          className="modal-overlay"
          onClick={e => e.target === e.currentTarget && setShowModal(false)}
          role="dialog"
          aria-modal="true"
          aria-labelledby="supplier-modal-title"
        >
          <div className="modal-sheet">
            <div className="modal-handle" aria-hidden="true" />
            <h2 id="supplier-modal-title" style={{ fontSize: 'var(--text-lg)', fontWeight: 700, marginBottom: 'var(--space-5)' }}>
              {editing ? 'Editar fornecedor' : 'Novo fornecedor'}
            </h2>

            <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--space-4)' }}>
              <div className="input-group">
                <label htmlFor="supplier-name" className="input-label">Nome *</label>
                <input
                  id="supplier-name"
                  type="text"
                  className="input"
                  placeholder="Ex: Casio do Brasil"
                  value={form.name}
                  onChange={e => setForm(f => ({ ...f, name: e.target.value }))}
                />
              </div>

              <div className="input-group">
                <label htmlFor="supplier-doc" className="input-label">CNPJ / CPF</label>
                <input
                  id="supplier-doc"
                  type="text"
                  className="input"
                  placeholder="Opcional"
                  value={form.document}
                  onChange={e => setForm(f => ({ ...f, document: e.target.value }))}
                />
              </div>

              <div className="input-group">
                <label htmlFor="supplier-notes" className="input-label">Observações</label>
                <input
                  id="supplier-notes"
                  type="text"
                  className="input"
                  placeholder="Informações adicionais"
                  value={form.notes}
                  onChange={e => setForm(f => ({ ...f, notes: e.target.value }))}
                />
              </div>

              <div style={{ display: 'flex', gap: 'var(--space-3)' }}>
                <button className="btn btn-secondary" style={{ flex: 1 }} onClick={() => setShowModal(false)}>
                  Cancelar
                </button>
                <button
                  id="btn-save-supplier"
                  className="btn btn-primary"
                  style={{ flex: 1 }}
                  onClick={handleSave}
                  disabled={saving}
                >
                  {saving ? 'Salvando...' : editing ? 'Salvar' : 'Cadastrar'}
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Delete confirmation */}
      {deleteTarget && (
        <div
          className="modal-overlay"
          onClick={e => e.target === e.currentTarget && setDeleteTarget(null)}
          role="dialog"
          aria-modal="true"
          aria-labelledby="delete-supplier-title"
        >
          <div className="modal-sheet">
            <div className="modal-handle" aria-hidden="true" />
            <div style={{ display: 'flex', alignItems: 'center', gap: 'var(--space-3)', marginBottom: 'var(--space-4)' }}>
              <div style={{ width: 48, height: 48, borderRadius: 'var(--radius-full)', background: 'var(--urgent-bg)', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                <AlertCircle size={24} color="var(--urgent)" />
              </div>
              <div>
                <h2 id="delete-supplier-title" style={{ fontSize: 'var(--text-base)', fontWeight: 700 }}>Excluir fornecedor?</h2>
                <p style={{ fontSize: 'var(--text-sm)', color: 'var(--text-muted)' }}>{deleteTarget.name}</p>
              </div>
            </div>
            <p style={{ fontSize: 'var(--text-sm)', color: 'var(--text-muted)', marginBottom: 'var(--space-5)' }}>
              Esta ação não pode ser desfeita. Boletos vinculados perderão a associação com este fornecedor.
            </p>
            <div style={{ display: 'flex', gap: 'var(--space-3)' }}>
              <button className="btn btn-secondary" style={{ flex: 1 }} onClick={() => setDeleteTarget(null)}>
                Cancelar
              </button>
              <button
                id="btn-confirm-delete-supplier"
                className="btn btn-danger"
                style={{ flex: 1 }}
                onClick={() => deleteMutation.mutate(deleteTarget.id)}
                disabled={deleteMutation.isPending}
              >
                {deleteMutation.isPending ? 'Excluindo...' : 'Excluir'}
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Floating icon for notes ref */}
      <div style={{ display: 'none' }}><FileText /></div>
    </main>
  );
}
