import { useState } from 'react';
import { useQuery } from '@tanstack/react-query';
import { supabase } from '../lib/supabase';
import { useAuth } from '../contexts/AuthContext';
import { formatCurrency } from '../lib/utils';
import { ArrowLeft, FileBarChart2, TrendingUp, DollarSign, AlertCircle, Download } from 'lucide-react';
import { useNavigate } from 'react-router-dom';
import type { BillView } from '../types/database';

type Period = 'month' | 'quarter' | 'year';

function useBillsForReport(orgId: string | undefined, period: Period) {
  return useQuery({
    queryKey: ['report-bills', orgId, period],
    queryFn: async () => {
      if (!orgId) return [];
      const now = new Date();
      let startDate: string;
      const endDate = new Date(now.getFullYear(), now.getMonth() + 1, 0).toISOString().split('T')[0];

      if (period === 'month') {
        startDate = new Date(now.getFullYear(), now.getMonth(), 1).toISOString().split('T')[0];
      } else if (period === 'quarter') {
        const q = Math.floor(now.getMonth() / 3);
        startDate = new Date(now.getFullYear(), q * 3, 1).toISOString().split('T')[0];
      } else {
        startDate = new Date(now.getFullYear(), 0, 1).toISOString().split('T')[0];
      }

      const { data, error } = await supabase
        .from('bills_view')
        .select('*')
        .eq('org_id', orgId)
        .gte('due_date', startDate)
        .lte('due_date', endDate)
        .order('due_date', { ascending: true });
      if (error) throw error;
      return (data ?? []) as BillView[];
    },
    enabled: !!orgId,
    staleTime: 60_000,
  });
}

const PERIOD_LABELS: Record<Period, string> = {
  month: 'Este mês',
  quarter: 'Este trimestre',
  year: 'Este ano',
};

export default function ReportsPage() {
  const { currentOrg } = useAuth();
  const navigate = useNavigate();
  const [period, setPeriod] = useState<Period>('month');

  const { data: bills = [], isLoading } = useBillsForReport(currentOrg?.org_id, period);

  // Aggregate stats
  const totalPaid = bills.filter(b => b.status === 'paid').reduce((s, b) => s + (b.paid_amount ?? b.amount), 0);
  const totalPending = bills.filter(b => b.status === 'pending').reduce((s, b) => s + b.amount, 0);
  const totalInterest = bills.reduce((s, b) => s + (b.interest_paid ?? 0), 0);
  const paidCount = bills.filter(b => b.status === 'paid').length;
  const pendingCount = bills.filter(b => b.status === 'pending').length;
  const overdueCount = bills.filter(b => b.urgency === 'urgent' && b.status === 'pending').length;

  // By category
  const byCategory = bills
    .filter(b => b.status === 'paid' && b.category_name)
    .reduce<Record<string, { name: string; amount: number; color: string | null; icon: string | null }>>((acc, b) => {
      const key = b.category_id ?? 'uncategorized';
      if (!acc[key]) acc[key] = { name: b.category_name!, amount: 0, color: b.category_color, icon: b.category_icon };
      acc[key].amount += b.paid_amount ?? b.amount;
      return acc;
    }, {});

  const categoryEntries = Object.entries(byCategory)
    .sort((a, b) => b[1].amount - a[1].amount)
    .slice(0, 8);

  const maxCategoryAmount = Math.max(...categoryEntries.map(([, v]) => v.amount), 1);

  // By supplier
  const bySupplier = bills
    .filter(b => b.status === 'paid' && b.supplier_name)
    .reduce<Record<string, { name: string; amount: number; count: number }>>((acc, b) => {
      const key = b.supplier_id ?? 'none';
      if (!acc[key]) acc[key] = { name: b.supplier_name!, amount: 0, count: 0 };
      acc[key].amount += b.paid_amount ?? b.amount;
      acc[key].count++;
      return acc;
    }, {});

  const supplierEntries = Object.entries(bySupplier)
    .sort((a, b) => b[1].amount - a[1].amount)
    .slice(0, 5);

  function handleExport() {
    // CSV export
    const rows = [
      ['Beneficiário', 'Fornecedor', 'Categoria', 'Valor', 'Vencimento', 'Status', 'Pago em', 'Valor pago', 'Juros/multa'],
      ...bills.map(b => [
        b.beneficiary_name ?? b.description ?? '',
        b.supplier_name ?? '',
        b.category_name ?? '',
        String(b.amount),
        b.due_date,
        b.status,
        b.paid_at ?? '',
        String(b.paid_amount ?? ''),
        String(b.interest_paid ?? 0),
      ]),
    ];
    const csv = rows.map(r => r.map(c => `"${String(c).replace(/"/g, '""')}"`).join(',')).join('\n');
    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `cronos-relatorio-${period}-${new Date().toISOString().slice(0, 10)}.csv`;
    a.click();
    URL.revokeObjectURL(url);
  }

  return (
    <main className="page" id="page-reports">
      <header className="page-header">
        <div className="container" style={{ display: 'flex', alignItems: 'center', gap: 'var(--space-3)' }}>
          <button className="btn-ghost btn-icon" onClick={() => navigate(-1)} aria-label="Voltar"
            style={{ width: 40, height: 40, minHeight: 40 }}>
            <ArrowLeft size={20} />
          </button>
          <h1 style={{ fontSize: 'var(--text-lg)', fontWeight: 700, flex: 1 }}>Relatórios</h1>
          <button
            className="btn btn-secondary"
            onClick={handleExport}
            id="btn-export-csv"
            aria-label="Exportar CSV"
            disabled={bills.length === 0}
          >
            <Download size={16} />
            <span className="desktop-only">Exportar CSV</span>
          </button>
        </div>
      </header>

      <div className="page-content container">
        {/* Period selector */}
        <div style={{ display: 'flex', gap: 'var(--space-2)', marginBottom: 'var(--space-2)' }}>
          {(['month', 'quarter', 'year'] as Period[]).map(p => (
            <button
              key={p}
              className={`chip ${period === p ? 'chip-brand' : 'chip-neutral'}`}
              onClick={() => setPeriod(p)}
              style={{ cursor: 'pointer', border: 'none' }}
              aria-pressed={period === p}
            >
              {PERIOD_LABELS[p]}
            </button>
          ))}
        </div>

        {isLoading ? (
          <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--space-3)' }}>
            {[...Array(4)].map((_, i) => (
              <div key={i} className="skeleton" style={{ height: 100, borderRadius: 'var(--radius-lg)' }} />
            ))}
          </div>
        ) : bills.length === 0 ? (
          <div className="empty-state">
            <div className="empty-state-circles">
              <div className="empty-circle empty-circle-1" />
              <div className="empty-circle empty-circle-2" />
              <FileBarChart2 size={48} color="var(--text-muted)" style={{ position: 'absolute', top: '50%', left: '50%', transform: 'translate(-50%, -50%)', zIndex: 1 }} aria-hidden="true" />
            </div>
            <h2>Sem dados para {PERIOD_LABELS[period].toLowerCase()}</h2>
            <p style={{ color: 'var(--text-muted)', fontSize: 'var(--text-sm)' }}>
              Adicione boletos para gerar relatórios detalhados.
            </p>
          </div>
        ) : (
          <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--space-4)' }}>
            {/* KPI cards */}
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(150px, 1fr))', gap: 'var(--space-3)' }}>
              <div className="card" style={{ padding: 'var(--space-4)' }}>
                <div style={{ display: 'flex', alignItems: 'center', gap: 'var(--space-2)', marginBottom: 'var(--space-2)' }}>
                  <DollarSign size={16} color="var(--ok)" />
                  <p style={{ fontSize: 'var(--text-xs)', color: 'var(--text-muted)', fontWeight: 600 }}>Pago</p>
                </div>
                <p className="amount" style={{ fontSize: 'var(--text-lg)', fontWeight: 800, color: 'var(--ok)' }}>
                  {formatCurrency(totalPaid)}
                </p>
                <p style={{ fontSize: 'var(--text-xs)', color: 'var(--text-muted)', marginTop: 2 }}>{paidCount} boleto{paidCount !== 1 ? 's' : ''}</p>
              </div>

              <div className="card" style={{ padding: 'var(--space-4)' }}>
                <div style={{ display: 'flex', alignItems: 'center', gap: 'var(--space-2)', marginBottom: 'var(--space-2)' }}>
                  <DollarSign size={16} color="var(--brand)" />
                  <p style={{ fontSize: 'var(--text-xs)', color: 'var(--text-muted)', fontWeight: 600 }}>A pagar</p>
                </div>
                <p className="amount" style={{ fontSize: 'var(--text-lg)', fontWeight: 800, color: 'var(--brand)' }}>
                  {formatCurrency(totalPending)}
                </p>
                <p style={{ fontSize: 'var(--text-xs)', color: 'var(--text-muted)', marginTop: 2 }}>{pendingCount} pendente{pendingCount !== 1 ? 's' : ''}</p>
              </div>

              <div className="card" style={{ padding: 'var(--space-4)' }}>
                <div style={{ display: 'flex', alignItems: 'center', gap: 'var(--space-2)', marginBottom: 'var(--space-2)' }}>
                  <AlertCircle size={16} color="var(--urgent)" />
                  <p style={{ fontSize: 'var(--text-xs)', color: 'var(--text-muted)', fontWeight: 600 }}>Atrasados</p>
                </div>
                <p className="amount" style={{ fontSize: 'var(--text-lg)', fontWeight: 800, color: overdueCount > 0 ? 'var(--urgent)' : 'var(--text-muted)' }}>
                  {overdueCount}
                </p>
                <p style={{ fontSize: 'var(--text-xs)', color: 'var(--text-muted)', marginTop: 2 }}>boleto{overdueCount !== 1 ? 's' : ''}</p>
              </div>

              <div className="card" style={{ padding: 'var(--space-4)' }}>
                <div style={{ display: 'flex', alignItems: 'center', gap: 'var(--space-2)', marginBottom: 'var(--space-2)' }}>
                  <TrendingUp size={16} color={totalInterest > 0 ? 'var(--urgent)' : 'var(--text-muted)'} />
                  <p style={{ fontSize: 'var(--text-xs)', color: 'var(--text-muted)', fontWeight: 600 }}>Juros/multas</p>
                </div>
                <p className="amount" style={{ fontSize: 'var(--text-lg)', fontWeight: 800, color: totalInterest > 0 ? 'var(--urgent)' : 'var(--text-muted)' }}>
                  {formatCurrency(totalInterest)}
                </p>
                <p style={{ fontSize: 'var(--text-xs)', color: 'var(--text-muted)', marginTop: 2 }}>
                  {totalInterest === 0 ? 'Nenhum!' : 'evitáveis'}
                </p>
              </div>
            </div>

            {/* By Category */}
            {categoryEntries.length > 0 && (
              <section className="card" aria-labelledby="by-cat-heading">
                <h2 id="by-cat-heading" style={{ fontSize: 'var(--text-sm)', fontWeight: 700, marginBottom: 'var(--space-4)', color: 'var(--text)' }}>
                  Gastos por categoria
                </h2>
                <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--space-3)' }}>
                  {categoryEntries.map(([key, cat]) => {
                    const pct = Math.round((cat.amount / maxCategoryAmount) * 100);
                    return (
                      <div key={key}>
                        <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: 4 }}>
                          <div style={{ display: 'flex', alignItems: 'center', gap: 'var(--space-2)' }}>
                            {cat.icon && <span style={{ fontSize: 16 }}>{cat.icon}</span>}
                            <span style={{ fontSize: 'var(--text-sm)', fontWeight: 600 }}>{cat.name}</span>
                          </div>
                          <span className="amount" style={{ fontSize: 'var(--text-sm)', fontWeight: 700 }}>{formatCurrency(cat.amount)}</span>
                        </div>
                        <div style={{ height: 6, background: 'var(--surface-2)', borderRadius: 999, overflow: 'hidden' }}>
                          <div style={{
                            height: '100%',
                            width: `${pct}%`,
                            background: cat.color ?? 'var(--brand)',
                            borderRadius: 999,
                            transition: 'width 0.5s ease',
                          }} />
                        </div>
                      </div>
                    );
                  })}
                </div>
              </section>
            )}

            {/* By Supplier */}
            {supplierEntries.length > 0 && (
              <section className="card" aria-labelledby="by-sup-heading">
                <h2 id="by-sup-heading" style={{ fontSize: 'var(--text-sm)', fontWeight: 700, marginBottom: 'var(--space-4)', color: 'var(--text)' }}>
                  Top fornecedores
                </h2>
                <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--space-3)' }}>
                  {supplierEntries.map(([key, sup], i) => (
                    <div key={key} style={{ display: 'flex', alignItems: 'center', gap: 'var(--space-3)' }}>
                      <span style={{
                        width: 24, height: 24, borderRadius: 'var(--radius-full)',
                        background: 'var(--surface-2)', display: 'flex', alignItems: 'center', justifyContent: 'center',
                        fontSize: 11, fontWeight: 700, color: 'var(--text-muted)', flexShrink: 0,
                      }}>
                        {i + 1}
                      </span>
                      <p style={{ flex: 1, fontWeight: 600, fontSize: 'var(--text-sm)', overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
                        {sup.name}
                      </p>
                      <div style={{ textAlign: 'right' }}>
                        <p className="amount" style={{ fontSize: 'var(--text-sm)', fontWeight: 700 }}>{formatCurrency(sup.amount)}</p>
                        <p style={{ fontSize: 'var(--text-xs)', color: 'var(--text-muted)' }}>{sup.count} boleto{sup.count !== 1 ? 's' : ''}</p>
                      </div>
                    </div>
                  ))}
                </div>
              </section>
            )}

            {/* All bills table */}
            <section className="card" aria-labelledby="all-bills-heading">
              <h2 id="all-bills-heading" style={{ fontSize: 'var(--text-sm)', fontWeight: 700, marginBottom: 'var(--space-4)', color: 'var(--text)' }}>
                Todos os boletos ({bills.length})
              </h2>
              <div style={{ overflowX: 'auto' }}>
                <table style={{ width: '100%', borderCollapse: 'collapse' }} role="table" aria-label="Tabela de boletos do período">
                  <thead>
                    <tr>
                      {['Beneficiário', 'Vencimento', 'Valor', 'Status'].map(col => (
                        <th key={col} style={{ textAlign: 'left', padding: 'var(--space-2) var(--space-3)', fontSize: 'var(--text-xs)', color: 'var(--text-muted)', fontWeight: 700, textTransform: 'uppercase', letterSpacing: '0.06em', borderBottom: '1px solid var(--border)', whiteSpace: 'nowrap' }}>
                          {col}
                        </th>
                      ))}
                    </tr>
                  </thead>
                  <tbody>
                    {bills.map(bill => (
                      <tr
                        key={bill.id}
                        style={{ cursor: 'pointer', transition: 'background 0.15s' }}
                        onClick={() => navigate(`/boletos/${bill.id}`)}
                        onMouseEnter={e => (e.currentTarget as HTMLElement).style.background = 'var(--surface-2)'}
                        onMouseLeave={e => (e.currentTarget as HTMLElement).style.background = 'transparent'}
                      >
                        <td style={{ padding: 'var(--space-2) var(--space-3)', fontSize: 'var(--text-sm)', maxWidth: 200, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
                          {bill.beneficiary_name ?? bill.description ?? '—'}
                        </td>
                        <td style={{ padding: 'var(--space-2) var(--space-3)', fontSize: 'var(--text-sm)', color: 'var(--text-muted)', whiteSpace: 'nowrap' }}>
                          {new Intl.DateTimeFormat('pt-BR').format(new Date(bill.due_date + 'T12:00'))}
                        </td>
                        <td className="amount" style={{ padding: 'var(--space-2) var(--space-3)', fontSize: 'var(--text-sm)', fontWeight: 700, whiteSpace: 'nowrap' }}>
                          {formatCurrency(bill.amount)}
                        </td>
                        <td style={{ padding: 'var(--space-2) var(--space-3)' }}>
                          <span className={`chip ${bill.urgency === 'urgent' ? 'chip-urgent' : bill.urgency === 'soon' ? 'chip-soon' : bill.status === 'paid' ? 'chip-paid' : 'chip-ok'}`} style={{ fontSize: 11 }}>
                            {bill.status === 'paid' ? 'Pago' : bill.urgency === 'urgent' ? 'Urgente' : bill.urgency === 'soon' ? 'Quase lá' : 'De boa'}
                          </span>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </section>
          </div>
        )}
      </div>
    </main>
  );
}
